def bellman_ford(n={{n}}, edges={{edges}}, src={{src}}):
    INF = float('inf')
    dist = [INF]*n; dist[src] = 0
    for _ in range(n-1):
        updated = False
        for u, v, w in edges:
            if dist[u] != INF and dist[u]+w < dist[v]:
                dist[v] = dist[u]+w; updated = True
        if not updated: break
    for u, v, w in edges:
        if dist[u] != INF and dist[u]+w < dist[v]:
            return None
    return dist
